package club.abelix.games.fakevival.config.defaults;

import org.bukkit.Material;
import org.bukkit.configuration.ConfigurationSection;

import java.util.*;

/** Exactly two hundred fixed, idempotent vanilla decorative collection paths. */
public final class DecorativeCollectionDefaults200 {
    private DecorativeCollectionDefaults200() {}

    private static final List<String> COLORS=List.of("WHITE","ORANGE","MAGENTA","LIGHT_BLUE","YELLOW","LIME","PINK","GRAY","LIGHT_GRAY","CYAN","PURPLE","BLUE","BROWN","GREEN","RED","BLACK");
    private static final List<String> FAMILIES=List.of("CONCRETE","CONCRETE_POWDER","TERRACOTTA","GLAZED_TERRACOTTA","STAINED_GLASS","STAINED_GLASS_PANE","CARPET","CANDLE","BED","BANNER","SHULKER_BOX","WALL_BANNER");
    private static final List<String> EXTRAS=List.of("PALE_MOSS_BLOCK","PALE_MOSS_CARPET","CREAKING_HEART","OPEN_EYEBLOSSOM","CLOSED_EYEBLOSSOM","RESIN_CLUMP","RESIN_BLOCK","RESIN_BRICKS");
    private static final int[] TIERS={50,100,250,500,1000,2500,5000,10000,25000,50000};

    public static void apply(ConfigurationSection root){for(Definition definition:definitions()){applyCollection(root,definition);applyMaterial(root,definition);applyRecipe(root,definition);}}
    public static Set<String> collectionIds(){LinkedHashSet<String>ids=new LinkedHashSet<>();definitions().forEach(d->ids.add(d.id()));return Set.copyOf(ids);}
    public static Set<String> materialIds(){LinkedHashSet<String>ids=new LinkedHashSet<>();definitions().forEach(d->ids.add(coreId(d)));return Set.copyOf(ids);}
    public static Set<String> recipeIds(){LinkedHashSet<String>ids=new LinkedHashSet<>();definitions().forEach(d->ids.add(outputId(d)));return Set.copyOf(ids);}

    private static List<Definition> definitions(){List<Definition>out=new ArrayList<>(200);for(String family:FAMILIES)for(String color:COLORS){String material=color+"_"+family;out.add(new Definition(normalize(material),material,category(family),icon(material)));}for(String material:EXTRAS)out.add(new Definition(normalize(material),material,category(material),icon(material)));if(out.size()!=200)throw new IllegalStateException("Decorative collection registry must contain exactly 200 paths");return List.copyOf(out);}

    private static void applyCollection(ConfigurationSection root,Definition definition){String base="collections.items."+definition.id();if(!root.isConfigurationSection(base)){root.set(base+".name","&e"+pretty(definition.id())+" Collection");root.set(base+".category",definition.category());root.set(base+".icon",definition.icon());root.set(base+".materials",List.of(definition.material()));}else{if(!root.contains(base+".category"))root.set(base+".category",definition.category());if(!root.contains(base+".icon"))root.set(base+".icon",definition.icon());List<String>tracked=new ArrayList<>(root.getStringList(base+".materials"));if(tracked.stream().noneMatch(definition.material()::equalsIgnoreCase))tracked.add(definition.material());root.set(base+".materials",tracked);}for(int tier=1;tier<=10;tier++){String path="collections."+definition.category()+"."+definition.id()+".tiers."+tier;if(!root.contains(path+".required"))root.set(path+".required",TIERS[tier-1]);if(!root.contains(path+".rewards")||root.getStringList(path+".rewards").isEmpty())root.set(path+".rewards",List.of("perk:tier_"+tier));}}

    private static void applyMaterial(ConfigurationSection root,Definition definition){String base="custom-items.items."+coreId(definition);if(root.isConfigurationSection(base))return;root.set(base+".name","&f"+pretty(definition.id())+" Artisan Core");root.set(base+".material",definition.icon());root.set(base+".type","RECIPE_MATERIAL");root.set(base+".mmo.type","RECIPE_MATERIAL");root.set(base+".category",materialCategory(definition.category()));root.set(base+".collection.category",definition.category());root.set(base+".recipe-material.category",definition.category());root.set(base+".rarity","COMMON");root.set(base+".random-rarity",false);root.set(base+".mmo.random-roll",false);root.set(base+".mmo.stats",null);root.set(base+".lore",List.of("&7A deterministic decorative recipe material."));root.set(base+".max-stack-size",64);root.set(base+".ability.type","none");root.set(base+".ability.mana-cost",0);root.set(base+".consumable.enabled",false);root.set(base+".unbreakable",false);root.set(base+".tradeable",true);root.set(base+".soulbound",false);root.set(base+".guild-sellable",true);root.set(base+".sellall-allowed",true);}

    private static void applyRecipe(ConfigurationSection root,Definition definition){Output output=output(definition);String id=outputId(definition),item="custom-items.items."+id,recipe="recipes."+id;if(!root.isConfigurationSection(item)){root.set(item+".name","&a"+pretty(definition.id())+" Artisan Relic");root.set(item+".material",output.material());root.set(item+".type",output.type());root.set(item+".mmo.type",output.type());root.set(item+".category",outputCategory(output.type()));root.set(item+".rarity","RARE");root.set(item+".random-rarity",false);root.set(item+".mmo.random-roll",false);root.set(item+".ability.type","none");root.set(item+".ability.mana-cost",0);root.set(item+".unbreakable",true);}if(!root.isConfigurationSection(recipe)){root.set(recipe+".display-name","&a"+pretty(definition.id())+" Artisan Relic");root.set(recipe+".category",recipeCategory(output.type()));root.set(recipe+".result",id);root.set(recipe+".unlock.type","COLLECTION");root.set(recipe+".unlock.collection",definition.id());root.set(recipe+".unlock.tier",4);root.set(recipe+".ingredients.A","custom:"+coreId(definition));root.set(recipe+".amounts.A",24);root.set(recipe+".ingredients.B","material:"+definition.icon());root.set(recipe+".amounts.B",8);root.set(recipe+".shape",List.of("AB ","   ","   "));}String tier="collections."+definition.category()+"."+definition.id()+".tiers.4";List<String>rewards=new ArrayList<>(root.getStringList(tier+".rewards"));String reward="recipe:"+id;if(!rewards.contains(reward))rewards.add(reward);root.set(tier+".rewards",rewards);}

    private static String category(String family){return switch(family){case"CARPET","BED","BANNER","WALL_BANNER","CANDLE"->"farming";case"PALE_MOSS_BLOCK","PALE_MOSS_CARPET","OPEN_EYEBLOSSOM","CLOSED_EYEBLOSSOM","CREAKING_HEART"->"foraging";default->"mining";};}
    private static String icon(String material){Material requested=Material.matchMaterial(material);if(requested!=null&&requested.isItem())return requested.name();if(material.endsWith("_WALL_BANNER"))return material.replace("_WALL_BANNER","_BANNER");return"CHEST";}
    private static String coreId(Definition definition){return definition.id()+"_artisan_core";}
    private static String outputId(Definition definition){return definition.id()+"_artisan_relic";}
    private static String materialCategory(String category){return category.equals("farming")?"farming_materials":category.equals("foraging")?"foraging_materials":"mining_materials";}
    private static Output output(Definition definition){String id=definition.id();if(id.endsWith("_concrete"))return new Output("IRON_CHESTPLATE","ARMOR");if(id.endsWith("_concrete_powder"))return new Output("IRON_BOOTS","ARMOR");if(id.endsWith("_glazed_terracotta"))return new Output(definition.icon(),"CHARM");if(id.endsWith("_terracotta"))return new Output("IRON_LEGGINGS","ARMOR");if(id.endsWith("_stained_glass_pane"))return new Output("IRON_SWORD","DAGGER");if(id.endsWith("_stained_glass"))return new Output("BLAZE_ROD","WAND");if(id.endsWith("_carpet"))return new Output("LEATHER_BOOTS","ARMOR");if(id.endsWith("_candle"))return new Output("BLAZE_ROD","WAND");if(id.endsWith("_bed"))return new Output(definition.icon(),"CHARM");if(id.endsWith("_wall_banner"))return new Output("GOLD_NUGGET","RING");if(id.endsWith("_banner"))return new Output(definition.icon(),"NECKLACE");if(id.endsWith("_shulker_box"))return new Output("TOTEM_OF_UNDYING","TOTEM");return new Output(definition.icon(),"CHARM");}
    private static String outputCategory(String type){return switch(type){case"ARMOR"->"armor";case"CHARM","RING","NECKLACE","TOTEM"->"accessories";case"WAND","STAFF"->"magic";default->"weapons";};}
    private static String recipeCategory(String type){return switch(type){case"ARMOR"->"ARMOR";case"CHARM","RING","NECKLACE","TOTEM"->"ACCESSORIES";case"WAND","STAFF"->"MAGIC";default->"WEAPONS";};}
    private static String normalize(String value){return value.toLowerCase(Locale.ROOT).replace('-','_').replace(' ','_');}
    private static String pretty(String value){StringBuilder out=new StringBuilder();for(String part:normalize(value).split("_")){if(!out.isEmpty())out.append(' ');out.append(Character.toUpperCase(part.charAt(0))).append(part.substring(1));}return out.toString();}
    private record Definition(String id,String material,String category,String icon){}
    private record Output(String material,String type){}
}
